// Compare local calendar dates rather than elapsed hours (a day can span 23 or 25 hours).
function calendarDay(date) {
  const midnight = new Date(0)
  midnight.setUTCFullYear(date.getFullYear(), date.getMonth(), date.getDate())
  return midnight.getTime() / MILLISECONDS_PER_DAY
